const cfg = $input.first().json;
const errors = [];
const spreadsheet = String(cfg.REGISTRY_SPREADSHEET_ID || '').trim();
if (!spreadsheet || spreadsheet === 'PASTE_YOUR_SPREADSHEET_ID') errors.push('Configure REGISTRY_SPREADSHEET_ID in Set Template Configuration.');
const tabFields = ['ANSWERS_TAB_NAME', 'EVIDENCE_TAB_NAME', 'DEPENDENCIES_TAB_NAME', 'REVIEW_QUEUE_TAB_NAME'];
for (const field of tabFields) {
  if (!String(cfg[field] || '').trim()) errors.push(field + ' must not be blank.');
}
const reviewDays = Number(cfg.DEFAULT_REVIEW_INTERVAL_DAYS);
if (!Number.isFinite(reviewDays) || reviewDays <= 0) errors.push('DEFAULT_REVIEW_INTERVAL_DAYS must be a positive number.');
const batchSize = Number(cfg.EVIDENCE_BATCH_SIZE);
if (!Number.isInteger(batchSize) || batchSize <= 0 || batchSize > 100) errors.push('EVIDENCE_BATCH_SIZE must be an integer from 1 to 100.');
const maxDigest = Number(cfg.MAX_DIGEST_ITEMS);
if (!Number.isInteger(maxDigest) || maxDigest <= 0 || maxDigest > 100) errors.push('MAX_DIGEST_ITEMS must be an integer from 1 to 100.');
const slackEnabled = cfg.SLACK_ALERTS_ENABLED === true || String(cfg.SLACK_ALERTS_ENABLED).toLowerCase() === 'true';
const slackChannel = String(cfg.SLACK_CHANNEL_ID || '').trim();
if (slackEnabled && (!slackChannel || slackChannel === 'PASTE_YOUR_SLACK_CHANNEL_ID')) errors.push('Configure SLACK_CHANNEL_ID before enabling Slack alerts.');
return [{ json: { ...cfg, SLACK_ALERTS_ENABLED: slackEnabled, configuration_valid: errors.length === 0, error_message: errors.join('; ') } }];

const clean = (name) => $(name).all().map((i) => i.json).filter((r) => r && Object.keys(r).length > 0);
const answers = clean('Read Security Answers');
const evidence = clean('Read Evidence Registry');
const dependencies = clean('Read Answer Evidence Dependencies');
const reviewQueue = clean('Read Existing Review Queue');
const errors = [];
const warnings = [];
const toBool = (v) => v === true || v === 1 || String(v).trim().toLowerCase() === 'true' || String(v).trim().toLowerCase() === 'yes';
const checkColumns = (rows, required, label) => {
  if (rows.length === 0) return;
  const first = rows[0];
  for (const column of required) {
    if (!Object.prototype.hasOwnProperty.call(first, column)) errors.push(label + ' is missing required column: ' + column);
  }
};
const checkUnique = (rows, field, label) => {
  const seen = new Set();
  for (const row of rows) {
    const value = String(row[field] || '').trim();
    if (!value) { errors.push(label + ' contains a blank ' + field + '.'); continue; }
    if (seen.has(value)) errors.push(label + ' contains duplicate ' + field + ': ' + value);
    seen.add(value);
  }
};
checkColumns(answers, ['answer_id','canonical_question','approved_answer','answer_owner','evidence_policy','last_approved_at','review_interval_days','manual_review_required','active','current_state','current_reason_codes','state_changed_at','last_audited_at'], 'Answers');
checkColumns(evidence, ['evidence_id','evidence_name','drive_file_id','evidence_type','evidence_owner','expires_at','active','last_seen_modified_time','last_seen_checksum','last_audited_at','current_evidence_state','last_error_code'], 'Evidence');
checkColumns(dependencies, ['dependency_id','answer_id','evidence_id','required','change_policy','notes'], 'Dependencies');
checkColumns(reviewQueue, ['review_item_key','run_id','answer_id','detected_state','reason_codes','affected_evidence_ids','detected_at','last_seen_at','status','resolved_at','reviewer_notes'], 'Review Queue');
checkUnique(answers, 'answer_id', 'Answers');
checkUnique(evidence, 'evidence_id', 'Evidence');
checkUnique(dependencies, 'dependency_id', 'Dependencies');
checkUnique(reviewQueue, 'review_item_key', 'Review Queue');
const answerIds = new Set(answers.map((r) => String(r.answer_id || '').trim()));
for (const row of answers) {
  const policy = String(row.evidence_policy || '').trim().toUpperCase();
  if (!['REQUIRED','OPTIONAL','NONE'].includes(policy)) errors.push('Unsupported evidence_policy for ' + row.answer_id + ': ' + policy);
}
for (const row of dependencies) {
  const policy = String(row.change_policy || '').trim().toUpperCase();
  if (!['INVALIDATE','REVIEW','IGNORE'].includes(policy)) errors.push('Unsupported change_policy for ' + row.dependency_id + ': ' + policy);
  const answerId = String(row.answer_id || '').trim();
  if (answerId && !answerIds.has(answerId)) warnings.push('Dependency ' + row.dependency_id + ' references unknown answer_id ' + answerId + ' and will be ignored.');
}
for (const row of reviewQueue) {
  const status = String(row.status || '').trim().toUpperCase();
  if (status && !['OPEN','RESOLVED'].includes(status)) errors.push('Unsupported Review Queue status for ' + row.review_item_key + ': ' + status);
}
const activeAnswerCount = answers.filter((r) => toBool(r.active)).length;
return [{ json: { registry_valid: errors.length === 0, error_message: errors.join('; '), registry_warnings: warnings, active_answer_count: activeAnswerCount, evidence_count: evidence.length, dependency_count: dependencies.length, review_queue_count: reviewQueue.length, run_id: $execution.id, audited_at: $now.toISO() } }];

const clean = (name) => $(name).all().map((i) => i.json).filter((r) => r && Object.keys(r).length > 0);
const answers = clean('Read Security Answers');
const evidence = clean('Read Evidence Registry');
const dependencies = clean('Read Answer Evidence Dependencies');
const toBool = (v) => v === true || v === 1 || String(v).trim().toLowerCase() === 'true' || String(v).trim().toLowerCase() === 'yes';
const activeAnswerIds = new Set(answers.filter((a) => toBool(a.active)).map((a) => String(a.answer_id).trim()));
const evidenceById = new Map(evidence.map((e) => [String(e.evidence_id || '').trim(), e]));
const referenced = new Set();
for (const dep of dependencies) {
  const answerId = String(dep.answer_id || '').trim();
  const evidenceId = String(dep.evidence_id || '').trim();
  if (activeAnswerIds.has(answerId) && evidenceId) referenced.add(evidenceId);
}
const out = [];
for (const evidenceId of referenced) {
  const row = evidenceById.get(evidenceId);
  if (!row) continue;
  if (!toBool(row.active)) continue;
  const driveFileId = String(row.drive_file_id || '').trim();
  if (!driveFileId) continue;
  out.push({ json: { has_evidence_to_audit: true, evidence_id: evidenceId, drive_file_id: driveFileId, evidence_name: String(row.evidence_name || ''), evidence_type: String(row.evidence_type || ''), evidence_owner: String(row.evidence_owner || ''), expires_at: String(row.expires_at || ''), last_seen_modified_time: String(row.last_seen_modified_time || ''), last_seen_checksum: String(row.last_seen_checksum || '') } });
}
if (out.length === 0) return [{ json: { has_evidence_to_audit: false } }];
return out;

const clean = (name) => $(name).all().map((i) => i.json).filter((r) => r && Object.keys(r).length > 0);
const answers = clean('Read Security Answers');
const evidence = clean('Read Evidence Registry');
const dependencies = clean('Read Answer Evidence Dependencies');
const reviewQueue = clean('Read Existing Review Queue');
const validation = $('Validate Registry Structure').first().json;
const toBool = (v) => v === true || v === 1 || String(v).trim().toLowerCase() === 'true' || String(v).trim().toLowerCase() === 'yes';
const observedRows = $input.all().map((i) => i.json).filter((r) => r && r.evidence_id && r.evidence_state);
const observedById = new Map(observedRows.map((r) => [String(r.evidence_id), r]));
const evidenceById = new Map(evidence.map((r) => [String(r.evidence_id || '').trim(), r]));
const activeAnswers = answers.filter((r) => toBool(r.active));
const activeAnswerIds = new Set(activeAnswers.map((r) => String(r.answer_id || '').trim()));
const graphAnswers = [];
const referencedEvidenceIds = new Set();
for (const answer of activeAnswers) {
  const answerId = String(answer.answer_id || '').trim();
  const deps = dependencies.filter((d) => String(d.answer_id || '').trim() === answerId).map((d) => {
    const evidenceId = String(d.evidence_id || '').trim();
    if (evidenceId) referencedEvidenceIds.add(evidenceId);
    return { dependency_id: String(d.dependency_id || ''), answer_id: answerId, evidence_id: evidenceId, required: toBool(d.required), change_policy: String(d.change_policy || '').trim().toUpperCase(), notes: String(d.notes || ''), evidence: evidenceById.get(evidenceId) || null, observed: observedById.get(evidenceId) || null };
  });
  graphAnswers.push({ answer, dependencies: deps });
}
const evidenceSnapshots = [];
for (const evidenceId of referencedEvidenceIds) {
  const row = evidenceById.get(evidenceId);
  if (!row) continue;
  const active = toBool(row.active);
  const driveFileId = String(row.drive_file_id || '').trim();
  const observed = observedById.get(evidenceId);
  let state = 'UNCERTAIN';
  let errorCode = 'LOOKUP_NOT_PERFORMED';
  let modifiedTime = String(row.last_seen_modified_time || '');
  let checksum = String(row.last_seen_checksum || '');
  if (!active) { state = 'INACTIVE'; errorCode = 'EVIDENCE_INACTIVE'; }
  else if (!driveFileId) { state = 'MISSING'; errorCode = 'MISSING_DRIVE_FILE_ID'; }
  else if (observed) {
    state = String(observed.evidence_state || 'UNCERTAIN');
    errorCode = String(observed.last_error_code || '');
    if (String(observed.current_modified_time || '')) modifiedTime = String(observed.current_modified_time);
    if (String(observed.current_checksum || '')) checksum = String(observed.current_checksum);
  }
  evidenceSnapshots.push({ evidence_id: evidenceId, drive_file_id: driveFileId, active, current_evidence_state: state, last_seen_modified_time: modifiedTime, last_seen_checksum: checksum, last_audited_at: String(validation.audited_at), last_error_code: errorCode });
}
return [{ json: { run_id: String(validation.run_id), audited_at: String(validation.audited_at), registry_warnings: validation.registry_warnings || [], answers: graphAnswers, evidence_snapshots: evidenceSnapshots, review_queue: reviewQueue, known_answer_ids: Array.from(activeAnswerIds) } }];

const context = $input.first().json;
const cfg = $('Set Template Configuration').first().json;
const nowIso = String(context.audited_at);
const nowMs = Date.parse(nowIso);
const defaultReviewDays = Number(cfg.DEFAULT_REVIEW_INTERVAL_DAYS);
const toBool = (v) => v === true || v === 1 || String(v).trim().toLowerCase() === 'true' || String(v).trim().toLowerCase() === 'yes';
const evaluations = [];
for (const entry of context.answers || []) {
  const answer = entry.answer || {};
  const deps = entry.dependencies || [];
  const answerId = String(answer.answer_id || '').trim();
  const missing = [];
  const review = [];
  const stale = [];
  const affected = new Set();
  const add = (bucket, code, evidenceId) => { bucket.push(code); if (evidenceId) affected.add(String(evidenceId)); };
  if (!String(answer.answer_owner || '').trim()) add(review, 'OWNER_MISSING');
  if (toBool(answer.manual_review_required)) add(review, 'MANUAL_REVIEW_REQUIRED');
  const approvedText = String(answer.last_approved_at || '').trim();
  const approvedMs = approvedText ? Date.parse(approvedText) : NaN;
  if (!approvedText || !Number.isFinite(approvedMs)) add(review, 'INVALID_LAST_APPROVED_AT');
  const intervalRaw = String(answer.review_interval_days ?? '').trim();
  const intervalDays = intervalRaw ? Number(intervalRaw) : defaultReviewDays;
  if (!Number.isFinite(intervalDays) || intervalDays <= 0) add(review, 'INVALID_REVIEW_INTERVAL');
  else if (Number.isFinite(approvedMs) && nowMs - approvedMs > intervalDays * 86400000) add(stale, 'ANSWER_REVIEW_INTERVAL_EXCEEDED');
  const evidencePolicy = String(answer.evidence_policy || '').trim().toUpperCase();
  if (evidencePolicy !== 'NONE') {
    const requiredDeps = deps.filter((d) => d.required === true);
    if (evidencePolicy === 'REQUIRED' && requiredDeps.length === 0) add(missing, 'REQUIRED_EVIDENCE_DEPENDENCY_MISSING');
    for (const dep of deps) {
      const evidenceId = String(dep.evidence_id || '').trim();
      const policy = String(dep.change_policy || '').trim().toUpperCase();
      const required = dep.required === true;
      const evidence = dep.evidence;
      const observed = dep.observed;
      if (!evidence) { if (required) add(missing, 'EVIDENCE_REGISTRY_RECORD_MISSING', evidenceId); else if (policy === 'REVIEW') add(review, 'OPTIONAL_EVIDENCE_MISSING', evidenceId); continue; }
      const evidenceActive = toBool(evidence.active);
      if (!evidenceActive) { if (required) add(stale, 'REQUIRED_EVIDENCE_DEACTIVATED', evidenceId); else if (policy === 'REVIEW') add(review, 'OPTIONAL_EVIDENCE_INACTIVE', evidenceId); continue; }
      if (!String(evidence.drive_file_id || '').trim()) { if (required) add(missing, 'MISSING_DRIVE_FILE_ID', evidenceId); else if (policy === 'REVIEW') add(review, 'OPTIONAL_EVIDENCE_MISSING', evidenceId); continue; }
      if (!observed) { add(review, 'EVIDENCE_LOOKUP_NOT_PERFORMED', evidenceId); continue; }
      const observedState = String(observed.evidence_state || '').toUpperCase();
      if (observedState === 'MISSING') { if (required) add(missing, 'EVIDENCE_NOT_FOUND', evidenceId); else if (policy === 'REVIEW') add(review, 'OPTIONAL_EVIDENCE_MISSING', evidenceId); continue; }
      if (observedState === 'UNCERTAIN') { add(review, 'EVIDENCE_ACCESS_UNCERTAIN', evidenceId); continue; }
      if (observedState === 'EXPIRED') { if (required) add(stale, 'EVIDENCE_EXPIRED', evidenceId); else if (policy === 'REVIEW') add(review, 'OPTIONAL_EVIDENCE_EXPIRED', evidenceId); continue; }
      if (observedState === 'AVAILABLE' && Number.isFinite(approvedMs)) {
        const modifiedText = String(observed.current_modified_time || '').trim();
        const modifiedMs = modifiedText ? Date.parse(modifiedText) : NaN;
        if (!modifiedText || !Number.isFinite(modifiedMs)) { if (policy !== 'IGNORE') add(review, 'INVALID_EVIDENCE_MODIFIED_TIME', evidenceId); }
        else if (modifiedMs > approvedMs) { if (policy === 'INVALIDATE') add(stale, 'EVIDENCE_MODIFIED_AFTER_APPROVAL', evidenceId); if (policy === 'REVIEW') add(review, 'EVIDENCE_CHANGED_REVIEW_POLICY', evidenceId); }
      }
    }
  }
  let state = 'CURRENT';
  if (missing.length > 0) state = 'MISSING EVIDENCE';
  else if (review.length > 0) state = 'REVIEW REQUIRED';
  else if (stale.length > 0) state = 'STALE';
  const reasons = Array.from(new Set([...missing, ...review, ...stale])).sort();
  const affectedEvidenceIds = Array.from(affected).sort();
  const previousState = String(answer.current_state || '').trim().toUpperCase();
  const previousReasons = String(answer.current_reason_codes || '').split(',').map((v) => v.trim()).filter(Boolean).sort();
  const stateChanged = previousState !== state;
  const reasonChanged = previousReasons.join(',') !== reasons.join(',');
  evaluations.push({ answer_id: answerId, previous_state: previousState, current_state: state, current_reason_codes: reasons.join(','), affected_evidence_ids: affectedEvidenceIds.join(','), state_changed: stateChanged, reason_changed: reasonChanged, state_changed_at: stateChanged ? nowIso : String(answer.state_changed_at || nowIso), last_audited_at: nowIso });
}
return [{ json: { ...context, evaluations } }];

const context = $input.first().json;
const nowIso = String(context.audited_at);
const queue = context.review_queue || [];
const existingUpdates = [];
const newItems = [];
const answerUpdates = [];
let recoveries = 0;
for (const evaluation of context.evaluations || []) {
  answerUpdates.push({ answer_id: evaluation.answer_id, current_state: evaluation.current_state, current_reason_codes: evaluation.current_reason_codes, state_changed_at: evaluation.state_changed_at, last_audited_at: evaluation.last_audited_at });
  const openForAnswer = queue.filter((q) => String(q.answer_id || '').trim() === evaluation.answer_id && String(q.status || '').trim().toUpperCase() === 'OPEN');
  if (evaluation.current_state === 'CURRENT') {
    if (evaluation.previous_state && evaluation.previous_state !== 'CURRENT') recoveries += 1;
    for (const old of openForAnswer) existingUpdates.push({ review_item_key: String(old.review_item_key || ''), last_seen_at: nowIso, status: 'RESOLVED', resolved_at: nowIso, detected_state: String(old.detected_state || ''), reason_codes: String(old.reason_codes || ''), affected_evidence_ids: String(old.affected_evidence_ids || '') });
    continue;
  }
  const key = [evaluation.answer_id, evaluation.current_state, evaluation.current_reason_codes, evaluation.affected_evidence_ids].join('|');
  const exact = openForAnswer.find((q) => String(q.review_item_key || '') === key);
  if (exact) {
    existingUpdates.push({ review_item_key: key, last_seen_at: nowIso, status: 'OPEN', resolved_at: '', detected_state: evaluation.current_state, reason_codes: evaluation.current_reason_codes, affected_evidence_ids: evaluation.affected_evidence_ids });
    continue;
  }
  for (const old of openForAnswer) existingUpdates.push({ review_item_key: String(old.review_item_key || ''), last_seen_at: nowIso, status: 'RESOLVED', resolved_at: nowIso, detected_state: String(old.detected_state || ''), reason_codes: String(old.reason_codes || ''), affected_evidence_ids: String(old.affected_evidence_ids || '') });
  newItems.push({ review_item_key: key, run_id: String(context.run_id), answer_id: evaluation.answer_id, detected_state: evaluation.current_state, reason_codes: evaluation.current_reason_codes, affected_evidence_ids: evaluation.affected_evidence_ids, detected_at: nowIso, last_seen_at: nowIso, status: 'OPEN', resolved_at: '' });
}
const counts = { CURRENT: 0, STALE: 0, 'MISSING EVIDENCE': 0, 'REVIEW REQUIRED': 0 };
for (const evaluation of context.evaluations || []) if (Object.prototype.hasOwnProperty.call(counts, evaluation.current_state)) counts[evaluation.current_state] += 1;
return [{ json: { run_id: String(context.run_id), audited_at: nowIso, registry_warnings: context.registry_warnings || [], evidence_updates: context.evidence_snapshots || [], answer_updates: answerUpdates, review_updates_existing: existingUpdates, review_appends_new: newItems, new_review_events: newItems.length, recoveries, counts } }];

const detect = $('Detect State Changes').first().json;
const rows = detect.evidence_updates || [];
if (rows.length === 0) return [{ json: { has_evidence_updates: false } }];
return rows.map((row) => ({ json: { has_evidence_updates: true, ...row } }));

const prepared = $('Prepare Review Queue Changes').first().json;
const rows = prepared.existing_updates || [];
if (rows.length === 0) return [{ json: { has_existing_review_updates: false } }];
return rows.map((row) => ({ json: { has_existing_review_updates: true, ...row } }));

const prepared = $('Prepare Review Queue Changes').first().json;
const rows = prepared.new_items || [];
if (rows.length === 0) return [{ json: { has_new_review_items: false } }];
return rows.map((row) => ({ json: { has_new_review_items: true, ...row } }));

const detect = $('Detect State Changes').first().json;
const rows = detect.answer_updates || [];
if (rows.length === 0) return [{ json: { has_answer_state_updates: false } }];
return rows.map((row) => ({ json: { has_answer_state_updates: true, ...row } }));

const detect = $('Detect State Changes').first().json;
const cfg = $('Set Template Configuration').first().json;
const notifyRecovery = cfg.NOTIFY_ON_RECOVERY === true || String(cfg.NOTIFY_ON_RECOVERY).toLowerCase() === 'true';
const onlyChanges = cfg.NOTIFY_ONLY_ON_NEW_OR_CHANGED === true || String(cfg.NOTIFY_ONLY_ON_NEW_OR_CHANGED).toLowerCase() === 'true';
const slackEnabled = cfg.SLACK_ALERTS_ENABLED === true || String(cfg.SLACK_ALERTS_ENABLED).toLowerCase() === 'true';
const eventCount = Number(detect.new_review_events || 0);
const recoveryCount = Number(detect.recoveries || 0);
const shouldNotify = onlyChanges ? (eventCount > 0 || (notifyRecovery && recoveryCount > 0)) : true;
return [{ json: { run_id: detect.run_id, audited_at: detect.audited_at, current_count: Number(detect.counts?.CURRENT || 0), stale_count: Number(detect.counts?.STALE || 0), missing_evidence_count: Number(detect.counts?.['MISSING EVIDENCE'] || 0), review_required_count: Number(detect.counts?.['REVIEW REQUIRED'] || 0), new_review_events: eventCount, recoveries: recoveryCount, should_notify: shouldNotify, slack_alerts_enabled: slackEnabled, registry_warning_count: Array.isArray(detect.registry_warnings) ? detect.registry_warnings.length : 0 } }];

const summary = $input.first().json;
const detect = $('Detect State Changes').first().json;
const cfg = $('Set Template Configuration').first().json;
const maxItems = Math.max(1, Math.min(100, Number(cfg.MAX_DIGEST_ITEMS || 20)));
const lines = [];
lines.push('*Security questionnaire freshness audit*');
lines.push('CURRENT: ' + summary.current_count + ' | STALE: ' + summary.stale_count + ' | MISSING EVIDENCE: ' + summary.missing_evidence_count + ' | REVIEW REQUIRED: ' + summary.review_required_count);
const newItems = detect.review_appends_new || [];
if (newItems.length > 0) {
  lines.push('');
  lines.push('*New or changed review items*');
  for (const item of newItems.slice(0, maxItems)) lines.push('- ' + item.answer_id + ' — ' + item.detected_state + ' — ' + (item.reason_codes || 'No reason code'));
  if (newItems.length > maxItems) lines.push('- +' + (newItems.length - maxItems) + ' additional item(s)');
}
if ((cfg.NOTIFY_ON_RECOVERY === true || String(cfg.NOTIFY_ON_RECOVERY).toLowerCase() === 'true') && Number(summary.recoveries || 0) > 0) {
  lines.push('');
  lines.push('Recovered to CURRENT: ' + summary.recoveries);
}
if (Number(summary.registry_warning_count || 0) > 0) {
  lines.push('');
  lines.push('Registry warnings: ' + summary.registry_warning_count);
}
return [{ json: { ...summary, digest_text: lines.join(String.fromCharCode(10)) } }];

const responses = $input.all();
const sources = $('Audit Evidence Files').all();
const out = [];
for (let index = 0; index < responses.length; index += 1) {
  const response = responses[index].json || {};
  const source = sources[index] ? sources[index].json : {};
  const statusCode = Number(response.statusCode || response.status || 0);
  const body = response.body && typeof response.body === 'object' ? response.body : {};
  const error = response.error || response.message || '';
  let retrievalStatus = 'OK';
  let errorCode = '';
  if (statusCode === 404) { retrievalStatus = 'NOT_FOUND'; errorCode = 'HTTP_404'; }
  else if (statusCode === 401 || statusCode === 403) { retrievalStatus = 'PERMISSION_DENIED'; errorCode = 'HTTP_' + statusCode; }
  else if (statusCode === 408 || statusCode === 429 || statusCode >= 500) { retrievalStatus = 'TRANSIENT_ERROR'; errorCode = statusCode ? 'HTTP_' + statusCode : 'TRANSIENT_REQUEST_ERROR'; }
  else if (statusCode && (statusCode < 200 || statusCode >= 300)) { retrievalStatus = 'API_ERROR'; errorCode = 'HTTP_' + statusCode; }
  else if (!statusCode && error) { retrievalStatus = 'TRANSIENT_ERROR'; errorCode = 'REQUEST_ERROR'; }
  out.push({ json: { ...source, retrieval_status: retrievalStatus, http_status: statusCode, current_modified_time: String(body.modifiedTime || ''), current_checksum: String(body.md5Checksum || ''), current_name: String(body.name || ''), current_mime_type: String(body.mimeType || ''), current_version: String(body.version || ''), trashed: body.trashed === true, last_error_code: errorCode, error_detail: typeof error === 'string' ? error : JSON.stringify(error) } });
}
return out;

const now = Date.now();
return $input.all().map((item) => {
  const row = item.json;
  let state = 'AVAILABLE';
  let errorCode = String(row.last_error_code || '');
  if (row.retrieval_status === 'NOT_FOUND' || row.trashed === true) { state = 'MISSING'; if (!errorCode) errorCode = row.trashed === true ? 'FILE_TRASHED' : 'FILE_NOT_FOUND'; }
  else if (row.retrieval_status !== 'OK') { state = 'UNCERTAIN'; if (!errorCode) errorCode = 'EVIDENCE_LOOKUP_FAILED'; }
  else if (String(row.expires_at || '').trim()) {
    const expiresMs = Date.parse(String(row.expires_at));
    if (!Number.isFinite(expiresMs)) { state = 'UNCERTAIN'; errorCode = 'INVALID_EXPIRES_AT'; }
    else if (expiresMs <= now) { state = 'EXPIRED'; errorCode = 'EVIDENCE_EXPIRED'; }
  }
  return { json: { ...row, evidence_state: state, last_error_code: errorCode } };
});
